1	import React, { type CSSProperties } from 'react';
2	import { Button as ChakraButton, IconButton, chakra, useStyleConfig, type SystemStyleObject } from '@chakra-ui/react';
3	import { ZimmIcon } from '../zimmIcon';
4	import type { ZimmIconType, ZimmIconSize } from '../zimmIcon';
5	
6	// All hover/press/focus/disabled interaction states live in zimmButton.css.ts, co-located
7	// beside this file. ZimmButton is a thin mapping layer: Zimmermann props (inverse,
8	// large/medium) → Chakra variant/size names that zimmButton.css.ts recognises.
9	
10	type ZimmButtonBaseProps = {
11	  /** Visible label (primary/secondary) or aria-label (icon variant — no visible text). */
12	  label: string;
13	  type?: 'button' | 'submit' | 'reset';
14	  disabled?: boolean;
15	  /**
16	   * Renders the disabled *appearance* while keeping the button focusable and in the Tab
17	   * order (A10) — HTML `disabled` removes it from the accessibility tree entirely, so screen
18	   * reader users can never reach it to hear why the action is unavailable. `onClick` is
19	   * suppressed here rather than by the DOM. Prefer this over `disabled` for
20	   * unavailable-but-explainable states (e.g. Add to Bag with an out-of-stock size selected).
21	   *
22	   * No recipe change is needed: Chakra's `_disabled` pseudo already expands to
23	   * `&:disabled, &[disabled], &[aria-disabled=true], &[data-disabled]`.
24	   */
25	  ariaDisabled?: boolean;
26	  inverse?: boolean;
27	  onClick?: () => void;
28	  style?: CSSProperties;
29	  /** Chakra `sx` passthrough — for a caller-owned recipe part, not a one-off inline style. */
30	  sx?: SystemStyleObject;
31	  /**
32	   * Accessible name, when it has to differ from the visible `label`. Defaults to `label`.
33	   * For a control whose visible text is only meaningful with context — e.g. a size filter
34	   * chip reading "0" that should announce "Add filter: 0" — pass the full phrase here and
35	   * keep `label` as the short visible text.
36	   */
37	  ariaLabel?: string;
38	};
39	
40	type ZimmLabelButtonProps = ZimmButtonBaseProps & {
41	  variant?: 'primary' | 'secondary';
42	  /** 'large' = 52px fixed · 'medium' = 40px fixed · 'adaptive' = 40px mobile → 52px desktop
43	   *  (same responsive size as the social variant, applied to primary/secondary colours). */
44	  size?: 'large' | 'medium' | 'adaptive';
45	  fullWidth?: boolean;
46	  /** Links an explanatory message element by id so screen readers announce it on focus. */
47	  ariaDescribedBy?: string;
48	  /** Optional icon rendered before the label. Pass a ZimmIcon or any React node. */
49	  iconLeading?: React.ReactNode;
50	  /** Optional icon rendered after the label. Pass a ZimmIcon or any React node. */
51	  iconTrailing?: React.ReactNode;
52	} & ({ role?: never; ariaChecked?: never } | { role: 'checkbox' | 'radio'; ariaChecked: boolean }); // `aria-checked` is a selectable control that never exposes what it is set to. // union so the role and its state cannot be supplied apart: a `role="checkbox"` with no // button and never conveys whether it is currently applied. Modelled as a discriminated // — e.g. a filter chip. Without these a screen reader announces the control as a plain // Toggle semantics, for a button that represents a *selectable state* rather than an action
53	
54	type ZimmIconButtonProps = ZimmButtonBaseProps & {
55	  variant: 'icon';
56	  icon: ZimmIconType;
57	  /** Icon render size — one of the iconSizes keys ('sm' | 'md' | 'lg'). Defaults to 'md' (16px). */
58	  size?: ZimmIconSize;
59	};
60	
61	type ZimmSocialButtonProps = ZimmButtonBaseProps & {
62	  variant: 'social';
63	  /** Icon node rendered to the left of the label (e.g. a brand logo SVG). */
64	  icon: React.ReactNode;
65	  /** Constrains the icon box to one of the four registered icon sizes. Defaults to 'md' (16px). */
66	  iconSize?: ZimmIconSize;
67	  /**
68	   * Inline style overrides for the icon box — use when the required size falls outside the
69	   * four registered `iconSize` steps (e.g. a 24 × 24 brand logo). Merged on top of the
70	   * `iconSize`-derived defaults, so it wins on specificity.
71	   */
72	  iconSx?: React.CSSProperties;
73	  /** Social buttons default to full width. Pass `false` to opt out. */
74	  fullWidth?: boolean;
75	};
76	
77	export type ZimmButtonProps = ZimmLabelButtonProps | ZimmIconButtonProps | ZimmSocialButtonProps;
78	
79	const ICON_SIZE_DEFAULT: ZimmIconSize = 'md';
80	
81	/** Atom — labelled button (primary/secondary) or icon-only button. All visual states
82	 *  are handled by `zimmButton.css.ts` (co-located beside this file) — no React state for hover/press/focus.
83	 *  Labelled variants accept optional `iconLeading` and `iconTrailing` nodes rendered either
84	 *  side of the label; gap between icon and text is set by the button's flex gap in baseStyle. */
85	export const ZimmButton = (props: ZimmButtonProps) => {
86	  const {
87	    label,
88	    type = 'button',
89	    disabled = false,
90	    ariaDisabled = false,
91	    inverse = false,
92	    onClick,
93	    style,
94	    sx,
95	    ariaLabel,
96	  } = props;
97	  // aria-disabled leaves the button clickable at the DOM level, so the no-op has to happen here.
98	  const handleClick = ariaDisabled ? undefined : onClick;
99	  const ariaDisabledAttr = ariaDisabled || undefined;
100	  const labelStyle = useStyleConfig('ZimmButtonLabel', {});
101	
102	  if (props.variant === 'icon') {
103	    return (
104	      <IconButton
105	        aria-label={ariaLabel ?? label}
106	        type={ariaDisabled ? 'button' : type}
107	        isDisabled={disabled}
108	        aria-disabled={ariaDisabledAttr}
109	        onClick={handleClick}
110	        variant={inverse ? 'iconInverse' : 'icon'}
111	        size="icon"
112	        icon={<ZimmIcon type={props.icon} size={props.size ?? ICON_SIZE_DEFAULT} aria-hidden={true} />}
113	        style={style}
114	        sx={sx}
115	      />
116	    );
117	  }
118	
119	  if (props.variant === 'social') {
120	    const iconSizeToken = props.iconSize ?? ICON_SIZE_DEFAULT;
121	    // Plain <span> (not chakra.span) so aria-hidden="true" is a guaranteed DOM attribute that
122	    // querySelector can find. chakra.span does not reliably forward aria-* to the DOM element
123	    // in jsdom (the styled-system prop handling swallows it). Styles are also applied inline
124	    // so toHaveStyle() resolves them without needing the Emotion CSS runtime.
125	    const iconBoxStyle: React.CSSProperties = {
126	      display: 'flex',
127	      alignItems: 'center',
128	      justifyContent: 'center',
129	      flexShrink: 0,
130	      width: `var(--zimm-icon-size-${iconSizeToken})`,
131	      height: `var(--zimm-icon-size-${iconSizeToken})`,
132	      ...props.iconSx,
133	    };
134	    // Width as inline style for the same reason — Chakra's width prop becomes a CSS class that
135	    // getComputedStyle doesn't resolve in jsdom; inline style is always queryable by toHaveStyle.
136	    const buttonStyle: React.CSSProperties = {
137	      ...(props.fullWidth !== false ? { width: '100%' } : {}),
138	      ...style,
139	    };
140	    return (
141	      <ChakraButton
142	        type={ariaDisabled ? 'button' : type}
143	        isDisabled={disabled}
144	        aria-disabled={ariaDisabledAttr}
145	        aria-label={ariaLabel ?? label}
146	        onClick={handleClick}
147	        variant="social"
148	        size="social"
149	        style={buttonStyle}
150	        sx={sx}
151	      >
152	        <span aria-hidden="true" style={iconBoxStyle}>
153	          {props.icon}
154	        </span>
155	        <chakra.span __css={labelStyle}>{label}</chakra.span>
156	      </ChakraButton>
157	    );
158	  }
159	
160	  const variant = props.variant ?? 'primary';
161	  // adaptive → reuses the 'social' Chakra size entry (same responsive height/padding tokens).
162	  const size = props.size === 'adaptive' ? 'social' : props.size === 'medium' ? 'sm' : 'lg';
163	  // Maps inverse prop to the *Inverse variant suffix defined in zimmButton.css.ts.
164	  const chakraVariant = `${variant}${inverse ? 'Inverse' : ''}`;
165	  const ariaDescribedBy = 'ariaDescribedBy' in props ? props.ariaDescribedBy : undefined;
166	  // The props type pairs these two, so no runtime guard is needed to keep aria-checked off a
167	  // plain action button.
168	  const role = 'role' in props ? props.role : undefined;
169	  const ariaChecked = 'ariaChecked' in props ? props.ariaChecked : undefined;
170	
171	  return (
172	    <ChakraButton
173	      type={ariaDisabled ? 'button' : type}
174	      isDisabled={disabled}
175	      aria-disabled={ariaDisabledAttr}
176	      // aria-label makes the accessible name explicit so VoiceOver doesn't read
177	      // CSS text-transform:uppercase as an acronym (e.g. "A-D-D to bag").
178	      aria-label={ariaLabel ?? label}
179	      aria-describedby={ariaDescribedBy}
180	      role={role}
181	      aria-checked={ariaChecked}
182	      onClick={handleClick}
183	      variant={chakraVariant}
184	      size={size}
185	      width={props.fullWidth ? '100%' : undefined}
186	      style={style}
187	      sx={sx}
188	    >
189	      {props.iconLeading && (
190	        <chakra.span aria-hidden={true} display="flex" alignItems="center" justifyContent="center" flexShrink={0}>
191	          {props.iconLeading}
192	        </chakra.span>
193	      )}
194	      <chakra.span __css={labelStyle}>{label}</chakra.span>
195	      {props.iconTrailing && (
196	        <chakra.span aria-hidden={true} display="flex" alignItems="center" justifyContent="center" flexShrink={0}>
197	          {props.iconTrailing}
198	        </chakra.span>
199	      )}
200	    </ChakraButton>
201	  );
202	};
203

