480	  const parentCategoryId = (category as { parentCategoryId?: string } | undefined)?.parentCategoryId;
481	
482	  // SFCC-847 — hierarchical category URL helpers. Categories are served at their slug path
483	  // (/clothing/dresses), never at /category/<id> (that route is excluded in routes.tsx).
484	  // location.pathname IS the current category's correct URL so it's used directly.
485	  // parentCategoryPath strips the last path segment (/clothing/dresses → /clothing).
486	  // siblingCategoryPath replaces the last path segment with the sibling's own last segment
487	  // (derived by stripping the parent-id prefix from the sibling's flat SFCC categoryId).
488	  const currentCategoryPath = location.pathname;
489	  const parentCategoryPath = currentCategoryPath.split('/').slice(0, -1).join('/') || '/';
490	
491	  // SFCC-847 — every selection in the drawer (category + every refinement facet) is
492	  // buffered locally via useFilterDrawerState rather than applied straight to the URL on
